async function processAiQuestion(i,env,ctx,uid,question,me){question=String(question||"").trim();if(!uid||!question)return reply("Bitte gib eine Frage ein.");if(me?.global_banned)return reply("Du bist global für VEXORA Bot gesperrt.");const developer=dev(uid,env),canProgram=developer||botRoleAtLeast(me,"moderator");if(isProgrammingRequest(question)&&!canProgram)return reply("🔒 Programmieren mit der VEXORA-KI ist dem globalen Bot-Rang **Moderator** oder **Admin** und dem Developer vorbehalten.");const chosenName=extractPreferredName(question);if(chosenName)me=await db(env,uid,{preferred_name:chosenName});const preferredName=me?.preferred_name||null;if(!env.AI||typeof env.AI.run!=="function")return reply("Die VEXORA-KI ist derzeit nicht verfügbar.\n\n-# VEXORA Bot Limits: nicht verfügbar");let used=null,limit=25;if(!developer){const usage=await economyRpc(env,"vexora_consume_ai_question",{p_user_id:uid,p_usage_date:aiUsageDate()});const quota=Array.isArray(usage)?usage[0]:usage;used=Number(quota?.used)||25;limit=Number(quota?.daily_limit)||25;if(!quota?.allowed)return reply(staticAiFallback(question,used,limit));}if(!ctx||typeof ctx.waitUntil!=="function")return reply("Die KI-Anfrage konnte gerade nicht gestartet werden."+aiLimitFooter(used,limit,developer));ctx.waitUntil(sendAiAnswer(i,env,question,used,limit,developer,preferredName));return{type:5}}
