function staticAiFallback(question,used,limit){
 const q=String(question||"").toLocaleLowerCase("de-DE").trim();
 let answer="";
 if(q.includes("vexora")||q.includes("was kann der bot")||q.includes("was macht der bot")) answer="VEXORA ist ein Discord-Bot für Serververwaltung und Roleplay. Bekannt sind unter anderem Fraktionen, Funk, Personalverwaltung, Moderationsbefehle, Logs und ein Dashboard.";
 else if(q.includes("hilfe")||q.includes("befehle")||q.includes("commands")||q.includes("slash")) answer="Bekannte VEXORA-Befehle: /vexora-hilfe, /vexora-status, /funk, /ai frage, /einstellen, /feuern, /kuendigen, /einstempeln und /ausstempeln. Welche Befehle du nutzen darfst, hängt von deinen Serverrollen ab.";
 else if(q.includes("fraktion")||q.includes("beruf")||q.includes("polizei")||q.includes("feuerwehr")||q.includes("rettungsdienst")||q.includes("sek")) answer="VEXORA unterstützt Roleplay-Fraktionen wie Polizei, Feuerwehr und Rettungsdienst sowie weitere eingerichtete Berufe. Die Leitstelle kann dich einstellen. Ein Job-Angebot musst du per Direktnachricht annehmen oder ablehnen.";
 else if(q.includes("einstellen")||q.includes("bewerb")||q.includes("job bekommen")||q.includes("beitreten")) answer="Für einen Job wende dich an die Leitstelle deines Servers. Wenn dir ein Job angeboten wird, erhältst du eine Direktnachricht und kannst das Angebot annehmen oder ablehnen.";
 else if(q.includes("kuendigen")||q.includes("kündigen")||q.includes("job verlassen")) answer="Zum Beenden deines aktiven Jobs gibt es den Befehl /kuendigen. Je nach Status musst du vorher aus dem Dienst ausgestempelt sein.";
 else if(q.includes("funk")||q.includes("funkspruch")) answer="Mit /funk kannst du – sofern du die nötigen Rechte hast und ein Funkkanal eingerichtet ist – eine Nachricht an den konfigurierten Funkkanal senden.";
 else if(q.includes("status")||q.includes("online")||q.includes("offline")) answer="Den aktuellen VEXORA-Botstatus kannst du mit /vexora-status prüfen.";
 else if(q.includes("server")||q.includes("invite")||q.includes("einladung")||q.includes("regeln")) answer="Konkrete Serverdaten wie Einladungslink, IP-Adresse oder individuelle Regeln sind in meinem festen Antwortwissen nicht hinterlegt. Bitte prüfe die Serverbeschreibung oder frage die Leitstelle.";
 else if(q.includes("limit")||q.includes("kontingent")||q.includes("fragen")) answer="Du hast täglich bis zu 25 KI-Fragen. Nach Verbrauch übernimmt das feste VEXORA-Antwortsystem. Es kann nur bekannte Hilfe- und Serverthemen beantworten; freie KI-Fragen sind dann nicht mehr möglich.";
 else answer="Das Tageslimit der KI ist erreicht. Das feste VEXORA-Ersatzsystem kann nur bekannte Bot-Befehle und allgemeine VEXORA-Informationen beantworten. Diese Frage benötigt die KI oder ist noch nicht als feste Antwort hinterlegt. Nutze /vexora-hilfe oder frage die Leitstelle.";
 return "⚠️ **Das Tageslimit ist erreicht – ein schwächeres, fest programmiertes System hat übernommen.**\n\n"+answer+aiLimitFooter(used,limit);
}
