const DASH_ORIGIN="https://dustinkawasaki.github.io";
const DASH_URL=DASH_ORIGIN+"/Vexora-funk/dashboard.html";
function cookieVal(req,name){const s=req.headers.get("Cookie")||"";for(const p of s.split(";")){const i=p.indexOf("=");if(i>0&&p.slice(0,i).trim()===name)return p.slice(i+1).trim()}return ""}
