function corsHeaders(req){const o=req.headers.get("Origin");const h={"Vary":"Origin","Access-Control-Allow-Methods":"GET,POST,PUT,OPTIONS","Access-Control-Allow-Headers":"Content-Type,Authorization","Access-Control-Allow-Credentials":"true"};if(o===DASH_ORIGIN)h["Access-Control-Allow-Origin"]=o;return h}
