async function sessionKey(env){if(!env.DASHBOARD_SESSION_SECRET||env.DASHBOARD_SESSION_SECRET.length<32)throw Error("DASHBOARD_SESSION_SECRET fehlt oder ist zu kurz");const d=await crypto.subtle.digest("SHA-256",encoder.encode(env.DASHBOARD_SESSION_SECRET));return crypto.subtle.importKey("raw",d,{name:"AES-GCM"},false,["encrypt","decrypt"])}
